package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.common.core.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;
public final class AiSafetyPolicy{private final JdbcTemplate jdbc;public AiSafetyPolicy(DataSource d){jdbc=new JdbcTemplate(d);}public void guard(String query,String category){var row=jdbc.query("SELECT knowledge_scope,sensitive_words FROM ai_prompt_config WHERE enabled=TRUE ORDER BY updated_at DESC LIMIT 1",r->r.next()?new String[]{r.getString(1),r.getString(2)}:null);if(row==null)return;String normalized=query.toLowerCase(Locale.ROOT);if(row[1]!=null)for(String word:row[1].split("[,;\\n\\r]+")){String w=word.strip().toLowerCase(Locale.ROOT);if(!w.isBlank()&&normalized.contains(w))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"问题包含不允许处理的敏感内容");}if(category!=null&&!category.isBlank()&&row[0]!=null&&!row[0].isBlank()){Set<String>allowed=new HashSet<>();for(String item:row[0].split("[,;\\n\\r]+"))allowed.add(item.strip().toUpperCase(Locale.ROOT));if(!allowed.contains(category.toUpperCase(Locale.ROOT)))throw new BusinessException(ErrorCode.PERMISSION_DENIED);}}}
